package dev.pedro.learning.ecommerce.notification.domain;import io.quarkus.hibernate.orm.panache.PanacheRepositoryBase;import jakarta.enterprise.context.ApplicationScoped;import java.util.UUID;@ApplicationScoped public class NotificationRepository implements PanacheRepositoryBase<NotificationEntity,UUID>{public NotificationEntity findByOrderId(UUID orderId){return find("orderId",orderId).firstResult();}}